 export type PortRange = [number, number];
+
+const MAX_PORT = 65535;
+
+function stripSpaces(text: string): string {
+  return text.replace(/^ +| +$/g, "");
+}
+
+function parsePort(text: string, item: string): number {
+  const digits = stripSpaces(text);
+  if (!/^\d+$/.test(digits)) {
+    throw new Error(`invalid port "${digits}" in item "${item}"`);
+  }
+  const port = Number(digits);
+  if (port < 1 || port > MAX_PORT) {
+    throw new Error(`port ${port} is outside 1-${MAX_PORT}`);
+  }
+  return port;
+}
+
+function parseItem(rawItem: string): PortRange {
+  const item = stripSpaces(rawItem);
+  if (item === "") {
+    throw new Error("empty item in port list");
+  }
+  const parts = item.split("-");
+  if (parts.length === 1) {
+    const port = parsePort(parts[0], item);
+    return [port, port];
+  }
+  if (parts.length !== 2) {
+    throw new Error(`invalid range "${item}"`);
+  }
+  const from = parsePort(parts[0], item);
+  const to = parsePort(parts[1], item);
+  if (to < from) {
+    throw new Error(`range end ${to} is below its start ${from}`);
+  }
+  return [from, to];
+}

